var _patchActive = false, _farmTarget = parseInt(localStorage.getItem("_dwFarmTarget")) || 1000;
var _menuVisible = false, _tripleTapCount = 0, _tripleTapTimer = null;
var _currentTab = "combat";

function _activatePatch() {
  if (_patchActive) return;
  _patchActive = true;
  showNotification("Patch ON! Vào PvP để auto farm cúp.", "success");
  _updatePatchBtn();
}

function _deactivatePatch() {
  if (!_patchActive) return;
  _patchActive = false;
  showNotification("<i class='fa-solid fa-power-off'></i> Patch OFF", "info");
  _updatePatchBtn();
}

function _updatePatchBtn() {
  var b = document.getElementById("_patchBtn");
  if (!b) return;
  b.innerHTML = _patchActive ? '<i class="fa-solid fa-pause"></i>' : '<i class="fa-solid fa-play"></i>';
  b.style.background = _patchActive ? "linear-gradient(135deg,#e74c3c,#c0392b)" : "linear-gradient(135deg,#2ecc71,#27ae60)";
}

function _switchTab(tab) {
  _currentTab = tab;
  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.tab === tab);
  });
  document.querySelectorAll('.tab-content').forEach(content => {
    content.style.display = content.dataset.tab === tab ? 'block' : 'none';
  });
}

function _initMenu() {
  if (document.getElementById("_mm")) return;

  if (!document.getElementById("_faCSS")) {
    var fa = document.createElement("link"); fa.id = "_faCSS"; fa.rel = "stylesheet";
    fa.href = "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css";
    document.head.appendChild(fa);
  }

  var s = document.createElement("style");
  s.textContent = `
    #_mmOv{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);z-index:99998;display:none;backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);opacity:0;transition:opacity .3s}
    #_mmOv.show{opacity:1}
    #_mm{position:fixed;z-index:99999;width:min(320px,88vw);border-radius:20px;background:linear-gradient(160deg,#2a1b4a 0%,#1e1238 100%);border:2px solid rgba(180,100,255,0.6);box-shadow:0 15px 50px rgba(0,0,0,0.6),0 0 30px rgba(180,100,255,0.25);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#fff;touch-action:none;display:none;transform:scale(0.9);opacity:0;transition:transform .35s cubic-bezier(.34,1.56,.64,1),opacity .3s;user-select:none}
    #_mm.show{transform:scale(1);opacity:1}
    #_mmH{background:linear-gradient(135deg,#6b46c1,#9f7aea);padding:14px 16px;cursor:move;display:flex;align-items:center;justify-content:space-between;border-radius:18px 18px 0 0}
    #_mmH h3{margin:0;font-size:15px;font-weight:700}
    .tabs{display:flex;background:rgba(0,0,0,0.3);border-radius:12px;margin:12px 12px 8px;padding:4px}
    .tab-btn{flex:1;padding:10px 12px;text-align:center;border-radius:10px;font-size:13px;font-weight:600;cursor:pointer;transition:all .2s}
    .tab-btn.active{background:#c4a1ff;color:#3f2a6b;box-shadow:0 4px 12px rgba(180,100,255,0.4)}
    #_mmB{padding:8px 16px 20px;max-height:58vh;overflow-y:auto}
    #_mmB::-webkit-scrollbar{width:4px}
    #_mmB::-webkit-scrollbar-thumb{background:#c4a1ff;border-radius:4px}
    .ms{margin-bottom:18px}
    .mst{font-size:11px;text-transform:uppercase;color:#c4a1ff;font-weight:700;margin-bottom:10px;letter-spacing:1px}
    .mt{display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.06);border:1px solid rgba(180,100,255,0.2);border-radius:14px;padding:14px;margin-bottom:10px}
    .mtl{font-size:14px;font-weight:500}
    .sw{position:relative;width:48px;height:28px;flex-shrink:0}
    .sw input{opacity:0;width:0;height:0}
    .sw .sl{position:absolute;cursor:pointer;inset:0;background:rgba(255,255,255,0.2);border-radius:28px;transition:.3s}
    .sw .sl:before{position:absolute;content:'';height:22px;width:22px;left:3px;bottom:3px;background:#fff;border-radius:50%;transition:.3s}
    .sw input:checked+.sl{background:#a78bfa}
    .sw input:checked+.sl:before{transform:translateX(20px)}
    .mb{background:linear-gradient(135deg,#8b5cf6,#6d28d9);border:none;color:#fff;padding:11px 16px;border-radius:12px;font-weight:600;cursor:pointer}
    .mb:active{transform:scale(0.95)}
    #_patchBtn{position:fixed;z-index:99997;width:56px;height:56px;border-radius:50%;border:3px solid rgba(255,255,255,0.25);color:#fff;font-size:22px;display:none;align-items:center;justify-content:center;cursor:pointer;bottom:85px;right:18px;transition:all .2s}
    #_patchBtn:active{transform:scale(0.85)}
  `;
  document.head.appendChild(s);

  var ov = document.createElement("div"); ov.id = "_mmOv";
  ov.onclick = () => _toggleMenu(false);
  document.body.appendChild(ov);

  var mm = document.createElement("div"); mm.id = "_mm";
  mm.innerHTML = `
    <div id="_mmH">
      <h3><i class="fa-solid fa-wand-magic-sparkles"></i> tinysweet DW</h3>
      <button id="_mmX" onclick="_toggleMenu(false)"><i class="fa-solid fa-xmark"></i></button>
    </div>
    <div class="tabs">
      <div class="tab-btn active" data-tab="combat" onclick="_switchTab('combat')">Combat</div>
      <div class="tab-btn" data-tab="settings" onclick="_switchTab('settings')">Settings</div>
      <div class="tab-btn" data-tab="info" onclick="_switchTab('info')">Info</div>
    </div>
    <div id="_mmB">
      <div class="tab-content" data-tab="combat">
        <div class="ms">
          <div class="mst"><i class="fa-solid fa-bolt"></i> AUTO FARM</div>
          <div class="mt">
            <div>
              <div class="mtl">Auto Farm Score</div>
              <div style="font-size:12px;color:#aaa">Tự động + cúp khi vào PvP</div>
            </div>
            <label class="sw">
              <input type="checkbox" id="_tgPatch" onchange="_togglePatch(this.checked)">
              <span class="sl"></span>
            </label>
          </div>
        </div>
      </div>
      <div class="tab-content" data-tab="settings" style="display:none">
        <div class="ms">
          <div class="mst"><i class="fa-solid fa-gear"></i> CÀI ĐẶT</div>
          <div class="mt">
            <div class="mtl">Mục tiêu Cúp</div>
            <input class="mi" id="_tTarget" type="number" value="${_farmTarget}" min="1" max="1000" style="width:90px;text-align:center">
          </div>
          <button class="mb" onclick="_applyTarget()" style="width:100%;margin-top:8px">
            <i class="fa-solid fa-check"></i> Lưu mục tiêu
          </button>
        </div>
      </div>
      <div class="tab-content" data-tab="info" style="display:none">
        <div class="ms">
          <div class="mst"><i class="fa-solid fa-circle-info"></i> THÔNG TIN</div>
          <div class="mt">
            <div>
              <div class="mtl"><i class="fa-brands fa-tiktok" style="color:#ff0050"></i> TikTok</div>
              <div class="mtd">@tinysweet_dev.gg</div>
            </div>
            <button class="mb" onclick="window.open('https://www.tiktok.com/@tinysweet_dev.gg','_blank')">
              <i class="fa-solid fa-arrow-up-right-from-square"></i>
            </button>
          </div>
          <div class="mt">
            <div>
              <div class="mtl"><i class="fa-brands fa-youtube" style="color:#ff0000"></i> YouTube</div>
              <div class="mtd">Tinysweet Channel</div>
            </div>
            <button class="mb" onclick="window.open('https://www.youtube.com/@iosmoddingz','_blank')">
              <i class="fa-solid fa-arrow-up-right-from-square"></i>
            </button>
          </div>
        </div>
      </div>
    </div>
  `;
  document.body.appendChild(mm);
  mm.style.left = "50%"; 
  mm.style.top = "50%"; 
  mm.style.transform = "translate(-50%,-50%) scale(0.9)";

  var fb = document.createElement("button"); fb.id = "_patchBtn";
  fb.innerHTML = '<i class="fa-solid fa-play"></i>';
  fb.style.background = "linear-gradient(135deg,#2ecc71,#27ae60)";
  document.body.appendChild(fb);

  fb.addEventListener("click", () => {
    _patchActive ? _deactivatePatch() : _activatePatch();
  });

  _makeDrag(mm, document.getElementById("_mmH"));
  _makeDragBtn(fb);

  document.addEventListener("touchstart", function(e) {
    if (e.touches.length >= 3) {
      _tripleTapCount++;
      if (_tripleTapCount === 1) {
        _tripleTapTimer = setTimeout(function(){ _tripleTapCount = 0; }, 600);
      }
      if (_tripleTapCount >= 2) {
        clearTimeout(_tripleTapTimer);
        _tripleTapCount = 0;
        _toggleMenu(!_menuVisible);
      }
    }
  }, {passive:true});
}

function _makeDrag(el, handle) {
  var ox=0,oy=0,mx=0,my=0,d=false;
  function s(e){ var t=e.touches?e.touches[0]:e; mx=t.clientX;my=t.clientY; var r=el.getBoundingClientRect();ox=r.left;oy=r.top;d=true;el.style.transform="none";el.style.transition="none"; }
  function m(e){ if(!d)return;var t=e.touches?e.touches[0]:e;el.style.left=(ox+t.clientX-mx)+"px";el.style.top=(oy+t.clientY-my)+"px";}
  function u(){d=false;}
  handle.addEventListener("mousedown",s);handle.addEventListener("touchstart",s,{passive:true});
  document.addEventListener("mousemove",m);document.addEventListener("touchmove",m,{passive:true});
  document.addEventListener("mouseup",u);document.addEventListener("touchend",u);
}

function _makeDragBtn(b) {
  var sx=0,sy=0,d=false,mv=false;
  function s(e){e.stopPropagation();var t=e.touches?e.touches[0]:e;sx=t.clientX-b.offsetLeft;sy=t.clientY-b.offsetTop;d=true;mv=false;b.style.transition="none";}
  function m(e){if(!d)return;var t=e.touches?e.touches[0]:e;b.style.left=(t.clientX-sx)+"px";b.style.top=(t.clientY-sy)+"px";b.style.right="auto";b.style.bottom="auto";mv=true;}
  function u(){d=false;setTimeout(function(){mv=false;},120);}
  b.addEventListener("mousedown",s);b.addEventListener("touchstart",s,{passive:false});
  document.addEventListener("mousemove",m);document.addEventListener("touchmove",m,{passive:true});
  document.addEventListener("mouseup",u);document.addEventListener("touchend",u);
}

function _togglePatch(show) {
  var b = document.getElementById("_patchBtn");
  if (b) b.style.display = show ? "flex" : "none";
  if (show) _activatePatch(); else _deactivatePatch();
}

function _applyTarget() {
  var inp = document.getElementById("_tTarget");
  var v = parseInt(inp.value) || 1000;
  if (v < 1) v = 1;
  if (v > 1000) v = 1000;
  _farmTarget = v;
  inp.value = v;
  try { localStorage.setItem("_dwFarmTarget", v); } catch(e){}
  showNotification(`<i class='fa-solid fa-crosshairs'></i> Mục tiêu: ${v} cúp`, "success");
}

function _toggleMenu(show) {
  _menuVisible = show;
  var mm = document.getElementById("_mm"), ov = document.getElementById("_mmOv");
  if (show) {
    if(mm){mm.style.display="block";requestAnimationFrame(function(){mm.classList.add("show");});}
    if(ov){ov.style.display="block";requestAnimationFrame(function(){ov.classList.add("show");});}
  } else {
    if(mm){mm.classList.remove("show");setTimeout(function(){mm.style.display="none";},300);}
    if(ov){ov.classList.remove("show");setTimeout(function(){ov.style.display="none";},250);}
  }
}

if(document.readyState==="complete"||document.readyState==="interactive"){
  setTimeout(_initMenu,1500);
} else {
  document.addEventListener("DOMContentLoaded",function(){setTimeout(_initMenu,1500);});
}


function showNotification(message = "Thông báo", type = "success") {
    if (!document.getElementById("fa-link")) {
        const link = document.createElement("link");
        link.id = "fa-link";
        link.rel = "stylesheet";
        link.href = "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css";
        document.head.appendChild(link);
    }

    if (!document.getElementById("toast-style")) {
        const style = document.createElement("style");
        style.id = "toast-style";
        style.innerHTML = `
            .toast-container {
                position: fixed;
                top: 20px;
                left: 50%;
                transform: translateX(-50%);
                z-index: 9999;
                display: flex;
                flex-direction: column;
                align-items: center;
                gap: 12px;
            }

            .toast {
                min-width: 280px;
                max-width: 90vw;
                padding: 14px 18px;
                border-radius: 14px;
                color: #fff;
                font-family: system-ui, sans-serif;
                backdrop-filter: blur(12px);
                background: rgba(20,20,20,0.75);
                box-shadow: 0 10px 30px rgba(0,0,0,0.4);
                display: flex;
                align-items: center;
                gap: 12px;
                opacity: 0;
                transform: translateY(-30px) scale(0.95);
                transition: all 0.35s ease;
            }

            .toast.show {
                opacity: 1;
                transform: translateY(0) scale(1);
            }

            .toast i {
                font-size: 18px;
            }

            .toast.success i { color: #4caf50; }
            .toast.error i { color: #f44336; }
            .toast.warning i { color: #ff9800; }
            .toast.info i { color: #2196f3; }

            .toast .close {
                margin-left: auto;
                cursor: pointer;
                opacity: 0.6;
                font-size: 14px;
            }

            .toast .close:hover {
                opacity: 1;
            }
        `;
        document.head.appendChild(style);
    }

    let container = document.querySelector(".toast-container");
    if (!container) {
        container = document.createElement("div");
        container.className = "toast-container";
        document.body.appendChild(container);
    }

    const icons = {
        success: "fa-check-circle",
        error: "fa-times-circle",
        warning: "fa-exclamation-triangle",
        info: "fa-circle-info"
    };

    // Keep max 2 toasts, remove oldest if more
    const oldToasts = container.querySelectorAll(".toast");
    if (oldToasts.length >= 2) {
      oldToasts[0].classList.remove("show");
      setTimeout(function(){ if(oldToasts[0].parentNode) oldToasts[0].remove(); }, 200);
    }

    const toast = document.createElement("div");
    toast.className = `toast ${type}`;
    toast.innerHTML = `
        <i class="fa-solid ${icons[type] || icons.info}"></i>
        <span>${message}</span>
        <i class="fa-solid fa-xmark close"></i>
    `;

    container.appendChild(toast);

    setTimeout(() => toast.classList.add("show"), 30);

    toast.querySelector(".close").onclick = () => removeToast(toast);

    setTimeout(() => removeToast(toast), 3500);

    function removeToast(el) {
        el.classList.remove("show");
        setTimeout(() => el.remove(), 300);
    }
}

showNotification("Đã load bundle", "success");


